<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\OAuthTokenException;
use Civi\Lughauth\Features\OAuth\Authentication\Application\TokenGranter\ResolverForClientCredentials;

final class ResolverForClientCredentialsUnitTest extends TestCase
{
    public function test_grants_requested_scopes_and_sets_sub_as_client_id(): void
    {
        $resolver = new ResolverForClientCredentials();
        $client = new ClientData('svc-api', ['client_credentials'], true, ['api:read', 'api:write'], 3600);

        $result = $resolver->authenticate('tenant-a', new AuthenticationRequest($client, '', ''), ['scope' => 'api:read unknown']);

        $this->assertTrue($result->valid);
        $this->assertSame('svc-api', $result->id);
        $this->assertSame('api:read', $result->scope);
    }

    public function test_without_scope_uses_all_allowed_scopes(): void
    {
        $resolver = new ResolverForClientCredentials();
        $client = new ClientData('svc-api', ['client_credentials'], true, ['api:read', 'api:write'], 3600);

        $result = $resolver->authenticate('tenant-a', new AuthenticationRequest($client, '', ''), []);

        $this->assertSame('api:read api:write', $result->scope);
    }

    public function test_invalid_scope_throws_oauth_exception(): void
    {
        $this->expectException(OAuthTokenException::class);
        $this->expectExceptionMessage('No requested scope is allowed for this client');

        $resolver = new ResolverForClientCredentials();
        $client = new ClientData('svc-api', ['client_credentials'], true, ['api:read'], 3600);
        $resolver->authenticate('tenant-a', new AuthenticationRequest($client, '', ''), ['scope' => 'api:admin']);
    }
}
